begin read only;
set local statement_timeout='20s';
select json_build_object('settings',json_build_object('enabled',s.enabled,'access_tier',s.access_tier,'standard_verified_at',s.standard_verified_at)) from pinterest_publish_settings s;
select json_build_object('rules',json_build_object('max_posts_per_day',r.max_posts_per_day,'min_gap_hours',r.min_gap_hours,'evergreen_reuse_days',r.evergreen_reuse_days)) from promotion_rules r where r.platform='pinterest' group by r.max_posts_per_day,r.min_gap_hours,r.evergreen_reuse_days;
select json_build_object('account',a.account_name,'handle',a.handle,'status',a.account_status,'category',cv.board_or_category,'drafts',count(*),'with_image',count(cv.image_url)) from publish_queue q join social_accounts a on a.id=q.social_account_id join content_variants cv on cv.id=q.content_variant_id where a.handle='sailing_981' and q.platform='pinterest' and q.status='draft' group by a.account_name,a.handle,a.account_status,cv.board_or_category;
select json_build_object('candidate',json_build_object('queue_id',q.id,'shop',s.shop_name,'listing_id',p.etsy_listing_id,'source_url',p.etsy_url,'category',cv.board_or_category,'image_url',cv.image_url,'destination_url',cv.destination_url,'title',cv.title,'body',cv.body,'handle',a.handle,'mapped',exists(select 1 from shop_social_accounts m where m.shop_id=q.shop_id and m.social_account_id=q.social_account_id and m.active),'history_count',(select count(*) from publish_history h where h.product_id=q.product_id and h.platform='pinterest'),'review_exists',exists(select 1 from pinterest_publish_reviews r where r.queue_id=q.id))) from publish_queue q join social_accounts a on a.id=q.social_account_id join content_variants cv on cv.id=q.content_variant_id join products p on p.id=q.product_id join shops s on s.id=q.shop_id where a.handle='sailing_981' and q.platform='pinterest' and q.status='draft' and cv.image_url is not null order by s.shop_name,p.etsy_listing_id limit 50;
commit;
